72	/// Accepts every decision schema in [`ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS`].
73	fn check_decision_schema_version<E: serde::de::Error>(found: u8, type_name: &str) -> Result<(), E> {
74	    if ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS.contains(&found) {
75	        return Ok(());
76	    }
77	    Err(E::custom(format!(
78	        "unsupported {type_name} schema version {found}; this build reads versions {:?}",
79	        ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS
80	    )))
81	}
