83	/// Credential-free, deterministic release authority derived by callisto-graph.
84	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
85	#[serde(rename_all = "camelCase", deny_unknown_fields)]
86	pub struct ReleaseDecisionV1 {
87	    pub schema_version: u8,
88	    pub entries: Vec<ReleaseDecisionEntry>,
89	    /// Workspace-relative, `/`-separated changeset paths the version commit deletes, sorted; absent before schema 3.
90	    #[serde(skip_serializing_if = "Option::is_none")]
91	    pub consumed_changesets: Option<Vec<String>>,
92	    pub digest: DecisionDigest,
93	}
