95	#[derive(Deserialize)]
96	#[serde(rename_all = "camelCase", deny_unknown_fields)]
97	struct ReleaseDecisionV1Wire {
98	    schema_version: u8,
99	    entries: Vec<ReleaseDecisionEntry>,
100	    #[serde(default)]
101	    consumed_changesets: Option<Vec<String>>,
102	    digest: DecisionDigest,
103	}
104	
105	impl<'de> Deserialize<'de> for ReleaseDecisionV1 {
106	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
107	    where
108	        D: Deserializer<'de>,
109	    {
110	        let wire = ReleaseDecisionV1Wire::deserialize(deserializer)?;
111	        check_decision_schema_version::<D::Error>(wire.schema_version, "release decision")?;
112	        let mut decision = Self::new(wire.entries).map_err(serde::de::Error::custom)?;
113	        match (wire.schema_version >= 3, wire.consumed_changesets) {
114	            (true, Some(consumed)) => decision = decision.consuming(consumed),
115	            (false, None) => {
116	                decision.schema_version = wire.schema_version;
117	                decision.consumed_changesets = None;
118	                decision.digest = decision_digest(&decision.entries, None);
119	            }
120	            (true, None) => return Err(serde::de::Error::missing_field("consumedChangesets")),
121	            (false, Some(_)) => {
122	                return Err(serde::de::Error::custom(format!(
123	                    "release decision schema version {} has no `consumedChangesets`",
124	                    wire.schema_version
125	                )))
126	            }
127	        }
128	        if decision.digest != wire.digest {
129	            return Err(serde::de::Error::custom(
130	                "release decision digest does not match canonical content",
131	            ));
132	        }
133	        Ok(decision)
134	    }
135	}
