137	impl ReleaseDecisionV1 {
138	    pub const SCHEMA_VERSION: u8 = 3;
139	    /// Version 1 lacks `unreleasedVersion` and versions 1 and 2 lack `consumedChangesets`; both still read.
140	    pub const READABLE_SCHEMA_VERSIONS: [u8; 3] = [1, 2, 3];
141	
142	    /// Records the changesets the version commit deletes, which release verification compares against the commit.
143	    pub fn consuming(mut self, changesets: impl IntoIterator<Item = String>) -> Self {
144	        let mut changesets: Vec<String> = changesets.into_iter().collect();
145	        changesets.sort();
146	        changesets.dedup();
147	        self.digest = decision_digest(&self.entries, Some(&changesets));
148	        self.consumed_changesets = Some(changesets);
149	        self
150	    }
151	
152	    /// Creates a canonical decision or rejects an ambiguous release roster.
153	    #[allow(clippy::result_large_err)]
154	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
155	        if entries.is_empty() {
156	            return Err(ReleaseDecisionError::EmptyRoster);
157	        }
158	        for entry in &mut entries {
159	            entry.reasons.sort();
160	            entry.reasons.dedup();
161	            if entry.reasons.is_empty() {
162	                return Err(ReleaseDecisionError::MissingReason {
163	                    package: entry.package.clone(),
164	                });
165	            }
166	        }
167	        entries.sort_by(|left, right| left.package.cmp(&right.package));
168	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
169	            return Err(ReleaseDecisionError::DuplicatePackage);
170	        }
171	
172	        // A fixed or linked group converges every member to one target version; checking it here
173	        // from the entries' own `FixedGroup`/`LinkedGroup` reasons also covers a decision
174	        // deserialized from a committed file (`Deserialize` calls `new()`).
175	        let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
176	        for entry in &entries {
177	            for reason in &entry.reasons {
178	                let group_id = match reason {
179	                    ReleaseInclusionReason::FixedGroup { group_id }
180	                    | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
181	                    _ => continue,
182	                };
183	                match group_targets.get(group_id) {
184	                    Some(existing) if **existing != entry.target_version => {
185	                        return Err(ReleaseDecisionError::DivergentGroupTarget {
186	                            group_id: group_id.to_string(),
187	                            left: (*existing).clone(),
188	                            right: entry.target_version.clone(),
189	                        });
190	                    }
191	                    _ => {
192	                        group_targets.insert(group_id, &entry.target_version);
193	                    }
194	                }
195	            }
196	        }
197	
198	        let digest = decision_digest(&entries, Some(&[]));
199	        Ok(Self {
200	            schema_version: Self::SCHEMA_VERSION,
201	            entries,
202	            consumed_changesets: Some(Vec::new()),
203	            digest,
204	        })
205	    }
206	}
207	
208	pub(super) fn decision_digest(entries: &[ReleaseDecisionEntry], consumed: Option<&[String]>) -> DecisionDigest {
209	    let mut transcript = CanonicalTranscript::decision_v1();
210	    for path in consumed.into_iter().flatten() {
211	        transcript.push_str("consumed-changeset", path);
212	    }
213	    for entry in entries {
214	        transcript.push_str("package", &entry.package.to_string());
215	        transcript.push_str("target-version", entry.target_version.render());
216	        for reason in &entry.reasons {
217	            transcript.push_str(
218	                "reason",
219	                &serde_json::to_string(reason).expect("closed reason serializes"),
220	            );
221	        }
222	    }
223	    DecisionDigest::from_transcript(&transcript)
224	}
