235	    MissingReason { package: ReleasePackageId },
236	    #[error("release decision claims divergent target versions for group `{group_id}`: {left} vs {right}")]
237	    DivergentGroupTarget {
238	        group_id: String,
239	        left: Version,
240	        right: Version,
241	    },
242	}
