1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! It records the exact package/version authority that later intent construction consumes, without
4	//! exposing a mutation route.
5	
6	use callisto_model::{
7	    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
8	    ReleaseInclusionReason, ReleasePackageId, Version,
9	};
10	
11	use super::git_batch::{batch_blobs, BatchBlob};
12	use crate::error::{
13	    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
14	    UnsupportedReleaseFeature,
15	};
16	use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
17	
18	/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
19	/// against `package`'s name.
20	///
21	/// This is the single derivation of release package identity shared by every
22	/// site that computes or verifies release authority: [`derive_release_decision`],
23	/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
24	/// Per this module's own established lesson (see the doc comment on
25	/// [`derive_release_commit_decision`]), independently reimplementing this
26	/// mapping at each call site is exactly the kind of duplicated derivation
27	/// that drifts -- so it lives here once instead.
28	pub(crate) fn release_package_ids(
29	    identity: &crate::IdentityIndex,
30	    package: &Package,
31	) -> Result<Vec<ReleasePackageId>, GraphError> {
32	    package
33	        .canonical_manifests()
34	        .map(|manifest| {
35	            let ecosystem = manifest.ecosystem();
36	            // A dual-manifest package's manifests may declare different names.
37	            let name = identity
38	                .native_name(&package.id, ecosystem)
39	                .unwrap_or(package.id.name());
40	            ReleasePackageId::new(ecosystem, name)
41	        })
42	        .collect::<Result<Vec<_>, _>>()
43	        .map_err(GraphError::from)
44	}
45	
46	/// Derives the durable roster from a freshly computed version plan.
47	///
48	/// The caller supplies the plan from the same workspace observation; this
49	/// function never inspects a caller-provided release roster.
50	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
51	    workspace: &Workspace<'_, R, D>,
52	    plan: &VersionPlan,
53	) -> Result<ReleaseDecisionV1, GraphError> {
54	    let mut package_ids = std::collections::BTreeMap::new();
55	    for package in workspace.graph.packages() {
56	        let ids = release_package_ids(&workspace.identity, package)?;
57	        package_ids.insert(package.id.clone(), ids);
58	    }
59	
60	    let mut entries = Vec::new();
61	    for bump in &plan.bumps {
62	        // `plan` derives from this observation, so a missing package id means an inconsistent pairing, not an operator error.
63	        let ids = package_ids
64	            .get(&bump.package)
65	            .ok_or_else(|| GraphError::ReleaseInvariant {
66	                detail: format!(
67	                    "version plan references package `{}`, which is absent from this workspace observation",
68	                    bump.package.display_name()
69	                ),
70	            })?;
71	        for id in ids {
72	            entries.push(ReleaseDecisionEntry {
73	                package: id.clone(),
74	                target_version: bump.to.clone(),
75	                reasons: vec![reason_from_bump(
76	                    &workspace.graph,
77	                    &bump.package,
78	                    id,
79	                    bump.reason.as_ref(),
80	                    &package_ids,
81	                )?],
82	            });
83	        }
84	    }
85	    let consumed = plan
86	        .consumed_changesets
87	        .iter()
88	        .map(|path| normalized_git_path(path))
89	        .collect::<Result<Vec<_>, _>>()?;
90	    Ok(ReleaseDecisionV1::new(entries)?.consuming(consumed))
91	}
92	
93	/// Derives a durable decision for explicit, exact release identities.
94	///
95	/// A linked group is one release unit: selecting any member includes every
96	/// member of that linked group which the version plan selected. All other
97	/// packages remain outside the authority boundary. The caller must pass
98	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
99	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
100	/// for release authority.
101	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
102	    workspace: &Workspace<'_, R, D>,
103	    plan: &VersionPlan,
104	    selections: &[ReleasePackageId],
105	) -> Result<ReleaseDecisionV1, GraphError> {
106	    let complete = derive_release_decision(workspace, plan)?;
107	
108	    let mut seen = std::collections::BTreeSet::new();
109	    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
110	        return Err(GraphError::ReleaseSelectionInvalid {
111	            package: duplicate.clone(),
112	            reason: ReleaseSelectionInvalidReason::Duplicate,
113	        });
114	    }
115	
116	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
117	    let owners = ReleaseOwners::of(workspace);
118	    let released = complete
119	        .entries
120	        .iter()
121	        .map(|entry| &entry.package)
122	        .collect::<std::collections::BTreeSet<_>>();
123	    for selection in &selected {
124	        let Some(package) = owners.get(selection) else {
125	            let missing = callisto_model::PackageId::Prefixed {
126	                ecosystem: selection.ecosystem(),
127	                name: selection.name().to_string(),
128	            };
129	            return Err(GraphError::unknown_package(
130	                missing,
131	                workspace.graph.packages().map(Package::canonical_id),
132	            ));
133	        };
134	        let reason = if !released.contains(*selection) {
135	            ReleaseSelectionInvalidReason::NotARelease
136	        } else if package
137	            .publish_to
138	            .iter()
139	            .all(|target| matches!(target, callisto_model::PublishTarget::None))
140	        {
141	            ReleaseSelectionInvalidReason::NoDispatchableTarget
142	        } else {
143	            continue;
144	        };
145	        return Err(GraphError::ReleaseSelectionInvalid {
146	            package: (*selection).clone(),
147	            reason,
148	        });
149	    }
150	
151	    let entries = expand_selection(workspace, &owners, complete.entries, &selected);
152	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
153	}
