155	/// Keeps the selected entries plus every entry sharing a fixed or linked group
156	/// with a selection. Both release routes narrow `--package` through this.
157	fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
158	    workspace: &Workspace<'_, R, D>,
159	    owners: &ReleaseOwners<'_>,
160	    entries: Vec<ReleaseDecisionEntry>,
161	    selected: &std::collections::BTreeSet<&ReleasePackageId>,
162	) -> Vec<ReleaseDecisionEntry> {
163	    // A plan-derived entry carries its linked group as a reason.
164	    let reason_groups = entries
165	        .iter()
166	        .filter(|entry| selected.contains(&entry.package))
167	        .flat_map(|entry| entry.reasons.iter())
168	        .filter_map(|reason| match reason {
169	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
170	            _ => None,
171	        })
172	        .collect::<std::collections::BTreeSet<_>>();
173	    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
174	    let config_groups = selected
175	        .iter()
176	        .flat_map(|selection| release_groups_of(workspace, owners, selection))
177	        .collect::<std::collections::BTreeSet<_>>();
178	    // Selecting one distribution of a package releases all of them, so the shared tag waits for every publish.
179	    let selected_packages = selected
180	        .iter()
181	        .filter_map(|selection| owners.get(selection))
182	        .map(|package| package.id.clone())
183	        .collect::<std::collections::BTreeSet<_>>();
184	    entries
185	        .into_iter()
186	        .filter(|entry| {
187	            selected.contains(&entry.package)
188	                || owners.get(&entry.package).is_some_and(|package| selected_packages.contains(&package.id))
189	                || entry.reasons.iter().any(|reason| {
190	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
191	                })
192	                || release_groups_of(workspace, owners, &entry.package)
193	                    .iter()
194	                    .any(|group| config_groups.contains(group))
195	        })
196	        .collect()
197	}
