199	/// Derives the roster of every publishable package whose current version has no tag in the canonical
200	/// [`crate::TagIndex`], each with [`ReleaseInclusionReason::UnreleasedVersion`], and keeps the tagged releases in
201	/// `resumable`: a tag does not prove the rest of the release was observed.
202	///
203	/// A non-empty `selections` restricts the roster to exactly those identities, each of which must be unreleased and
204	/// publishable. `None` means nothing is unreleased.
205	pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
206	    workspace: &Workspace<'_, R, D>,
207	    selections: &[ReleasePackageId],
208	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
209	) -> Result<Option<ReleaseDecisionV1>, GraphError> {
210	    let versions = workspace.base_versions()?;
211	    let tags = workspace.tags()?;
212	    let mut entries = Vec::new();
213	    for package in workspace.graph.packages() {
214	        if !has_dispatchable_target(package) {
215	            continue;
216	        }
217	        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
218	            detail: format!("package `{}` has no base version", package.id.display_name()),
219	        })?;
220	        let ids = release_package_ids(&workspace.identity, package)?;
221	        if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
222	            continue;
223	        }
224	        for id in ids {
225	            entries.push(ReleaseDecisionEntry {
226	                package: id,
227	                target_version: version.clone(),
228	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
229	            });
230	        }
231	    }
232	
233	    let mut seen = std::collections::BTreeSet::new();
234	    let owners = ReleaseOwners::of(workspace);
235	    let unreleased = entries
236	        .iter()
237	        .map(|entry| entry.package.clone())
238	        .collect::<std::collections::BTreeSet<_>>();
239	    for selection in selections {
240	        if !seen.insert(selection) {
241	            return Err(GraphError::ReleaseSelectionInvalid {
242	                package: selection.clone(),
243	                reason: ReleaseSelectionInvalidReason::Duplicate,
244	            });
245	        }
246	        let Some(package) = owners.get(selection) else {
247	            let missing = callisto_model::PackageId::Prefixed {
248	                ecosystem: selection.ecosystem(),
249	                name: selection.name().to_string(),
250	            };
251	            return Err(GraphError::unknown_package(
252	                missing,
253	                workspace.graph.packages().map(Package::canonical_id),
254	            ));
255	        };
256	        if !has_dispatchable_target(package) {
257	            return Err(GraphError::ReleaseSelectionInvalid {
258	                package: selection.clone(),
259	                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
260	            });
261	        }
262	        if !unreleased.contains(selection) {
263	            return Err(GraphError::ReleaseSelectionInvalid {
264	                package: selection.clone(),
265	                reason: ReleaseSelectionInvalidReason::NotARelease,
266	            });
267	        }
268	    }
269	    if !selections.is_empty() {
270	        entries = expand_selection(workspace, &owners, entries, &seen);
271	    }
272	    if entries.is_empty() {
273	        return Ok(None);
274	    }
275	    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
276	}
