278	/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
279	pub(crate) fn version_is_tagged(
280	    tags: &crate::TagIndex,
281	    package: &callisto_model::PackageId,
282	    version: &Version,
283	) -> bool {
284	    tag_of_version(tags, package, version).is_some()
285	}
