287	pub(crate) fn tag_of_version(
288	    tags: &crate::TagIndex,
289	    package: &callisto_model::PackageId,
290	    version: &Version,
291	) -> Option<String> {
292	    let rendered = tags.template(package).render(version).to_string();
293	    if tags.is_tag_of(package, &rendered) {
294	        return Some(rendered);
295	    }
296	    tags.last_tag(package)
297	        .filter(|tag| &tag.version == version)
298	        .map(|tag| tag.name.to_string())
299	}
