301	/// Entries for every publishable package whose current version is tagged on `source`.
302	///
303	/// A run that created such a tag may have stopped before pushing it or finishing the release.
304	pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
305	    workspace: &Workspace<'_, R, D>,
306	    source: &CommitSha,
307	) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
308	    let versions = workspace.base_versions()?;
309	    let tags = workspace.tags()?;
310	    let git = workspace.git_access();
311	    let mut entries = Vec::new();
312	    for package in workspace.graph.packages() {
313	        if !has_dispatchable_target(package) {
314	            continue;
315	        }
316	        let Some(version) = versions.get(&package.id) else {
317	            continue;
318	        };
319	        // Only the tag this run's tag operation would create: one made under an older template is another release's.
320	        let tag = tags.template(&package.id).render(version).to_string();
321	        if !tags.contains_tag(&tag) {
322	            continue;
323	        }
324	        if tags.commit_of(git, &tag)?.as_ref() != Some(source) {
325	            continue;
326	        }
327	        for id in release_package_ids(&workspace.identity, package)? {
328	            entries.push(ReleaseDecisionEntry {
329	                package: id,
330	                target_version: version.clone(),
331	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
332	            });
333	        }
334	    }
335	    Ok(entries)
336	}
