345	/// Each release identity's workspace package, built once so a lookup per entry does not rescan every package.
346	pub(crate) struct ReleaseOwners<'w>(std::collections::BTreeMap<ReleasePackageId, &'w Package>);
347	
348	impl<'w> ReleaseOwners<'w> {
349	    pub(crate) fn of<R: callisto_model::CommandRunner, D: DependencyResolver>(
350	        workspace: &'w Workspace<'_, R, D>,
351	    ) -> Self {
352	        let mut owners = std::collections::BTreeMap::new();
353	        // By release identity, not name: a dual-manifest package's npm name can differ from its id.
354	        for package in workspace.graph.packages() {
355	            for id in release_package_ids(&workspace.identity, package).unwrap_or_default() {
356	                owners.entry(id).or_insert(package);
357	            }
358	        }
359	        Self(owners)
360	    }
361	
362	    /// The workspace package with this exact release identity.
363	    pub(crate) fn get(&self, id: &ReleasePackageId) -> Option<&'w Package> {
364	        self.0.get(id).copied()
365	    }
366	}
