368	/// The fixed and linked groups a release package belongs to, per config.
369	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
370	    workspace: &Workspace<'_, R, D>,
371	    owners: &ReleaseOwners<'_>,
372	    id: &ReleasePackageId,
373	) -> Vec<(&'static str, callisto_model::GroupName)> {
374	    let Some(package) = owners.get(id) else {
375	        return Vec::new();
376	    };
377	    let groups = &workspace.config.groups;
378	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
379	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
380	    // Member keys are canonical, so compare exactly; `PackageId::matches` would treat a Bare key as an ecosystem wildcard.
381	    fixed
382	        .chain(linked)
383	        .filter(|(_, member, _)| **member == package.id)
384	        .map(|(kind, _, group)| (kind, group.clone()))
385	        .collect()
386	}
