388	/// Verifies the release roster a merged release commit claims, against a
389	/// release-decision file committed alongside it at `decision_path`.
390	///
391	/// This is intentionally *not* a second computation of changeset, fixed-group,
392	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
393	/// (via [`derive_release_decision`]) already computed that once, correctly,
394	/// when the release PR was generated -- and `callisto version --emit-decision`
395	/// commits its exact output alongside the manifest and changelog edits.
396	/// Re-deriving that policy here from raw git diffs would duplicate logic that drifts (it would miss, for
397	/// instance, a fixed-group cascade that touches an unnamed sibling), so this function reads the committed
398	/// decision back and confirms the commit's actual diff matches it exactly -- no more, no less.
399	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
400	/// entries don't match its content digest, so a hand-edited or corrupted
401	/// decision file fails before this function's own diff cross-check runs.
402	///
403	/// The caller must check out the exact merge commit in detached HEAD state
404	/// before creating an intent. GitHub-specific PR/approval provenance belongs
405	/// in the workflow boundary; this graph function verifies the local,
406	/// provider-neutral commit delta only.
407	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
408	    workspace: &Workspace<'_, R, D>,
409	    release_commit: &CommitSha,
410	    decision_path: &std::path::Path,
411	) -> Result<ReleaseDecisionV1, GraphError> {
412	    let (parent, changed) = commit_delta(workspace, release_commit)?;
413	    let decision_path_str = normalized_git_path(decision_path)?;
414	    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
415	    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
416	    require_recorded_changesets_consumed(workspace, release_commit, &changed, &decision)?;
417	    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
418	    Ok(decision)
419	}
420	
421	/// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
422	/// release commit.
423	fn commit_delta<R: CommandRunner, D: DependencyResolver>(
424	    workspace: &Workspace<'_, R, D>,
425	    release_commit: &CommitSha,
426	) -> Result<(String, Vec<(String, String)>), GraphError> {
427	    let head_args = ["rev-parse", "HEAD"];
428	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
429	    let head =
430	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
431	    if &head != release_commit {
432	        return Err(GraphError::ReleaseCommitVerificationFailed {
433	            commit: release_commit.clone(),
434	            reason: CommitVerificationFailure::HeadMismatch,
435	        });
436	    }
437	
438	    let parent_ref = format!("{}^", release_commit.as_str());
439	    let parent_args = ["rev-parse", parent_ref.as_str()];
440	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
441	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
442	
443	    let diff_tree_args = [
444	        "diff-tree",
445	        "--no-commit-id",
446	        "--name-status",
447	        "-r",
448	        "--no-renames",
449	        parent.as_str(),
450	        release_commit.as_str(),
451	    ];
452	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
453	    let mut changed = parse_name_status(&changed, &diff_tree_args)?;
454	
455	    // `diff-tree` paths are repository-top-relative. Rewrite them workspace-relative; an edit outside the workspace
456	    // becomes `../..` so it never matches a workspace path and is still refused as unexpected.
457	    let prefix = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "--show-prefix"])?;
458	    let up = "../".repeat(prefix.matches('/').count());
459	    for (_, path) in &mut changed {
460	        *path = match path.strip_prefix(prefix.as_str()) {
461	            Some(inside) => inside.to_owned(),
462	            None => format!("{up}{path}"),
463	        };
464	    }
465	    Ok((parent, changed))
466	}
