468	/// The commit has the shape of a version commit: it wrote the decision and touched only the paths a version commit may
469	/// touch.
470	fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
471	    workspace: &Workspace<'_, R, D>,
472	    release_commit: &CommitSha,
473	    changed: &[(String, String)],
474	    decision_path: &str,
475	) -> Result<(), GraphError> {
476	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
477	
478	    // The decision must be written by this commit, not left over from an earlier release.
479	    let decision_freshly_written = changed
480	        .iter()
481	        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
482	    if !decision_freshly_written {
483	        return Err(GraphError::ReleaseCommitVerificationFailed {
484	            commit: release_commit.clone(),
485	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
486	        });
487	    }
488	
489	    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
490	    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
491	    // or where, under the cover of a bot-authored diff.
492	    let changelogs = workspace
493	        .graph
494	        .packages()
495	        .filter_map(|package| package.changelog.as_deref())
496	        .map(normalized_git_path)
497	        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
498	    for (_, path) in changed {
499	        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
500	            return Err(GraphError::ReleaseCommitVerificationFailed {
501	                commit: release_commit.clone(),
502	                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
503	            });
504	        }
505	    }
506	    Ok(())
507	}
508	
509	/// The commit deletes exactly the changesets the decision recorded. A decision from before that record must delete at
510	/// least one, since every release then started from a changeset.
511	fn require_recorded_changesets_consumed<R: CommandRunner, D: DependencyResolver>(
512	    workspace: &Workspace<'_, R, D>,
513	    release_commit: &CommitSha,
514	    changed: &[(String, String)],
515	    decision: &ReleaseDecisionV1,
516	) -> Result<(), GraphError> {
517	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
518	    let deleted: std::collections::BTreeSet<&str> = changed
519	        .iter()
520	        .filter(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir))
521	        .map(|(_, path)| path.as_str())
522	        .collect();
523	    let consumed_as_recorded = match &decision.consumed_changesets {
524	        Some(recorded) => recorded.iter().map(String::as_str).eq(deleted.iter().copied()),
525	        None => !deleted.is_empty(),
526	    };
527	    if !consumed_as_recorded {
528	        return Err(GraphError::ReleaseCommitVerificationFailed {
529	            commit: release_commit.clone(),
530	            reason: CommitVerificationFailure::ConsumedChangesetsDiffer,
531	        });
532	    }
533	    Ok(())
534	}
