536	/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
537	fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
538	    workspace: &Workspace<'_, R, D>,
539	    release_commit: &CommitSha,
540	    decision_path: &std::path::Path,
541	    decision_path_str: &str,
542	) -> Result<ReleaseDecisionV1, GraphError> {
543	    let decision_source = git_file(
544	        workspace.runner,
545	        &workspace.root,
546	        release_commit.as_str(),
547	        decision_path_str,
548	    )?;
549	    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
550	        path: decision_path.to_path_buf(),
551	        message: error.to_string(),
552	    })
553	}
554	
555	/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
556	/// no package the decision does not claim changed version.
557	fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
558	    workspace: &Workspace<'_, R, D>,
559	    release_commit: &CommitSha,
560	    parent: &str,
561	    changed: &[(String, String)],
562	    decision: &ReleaseDecisionV1,
563	) -> Result<(), GraphError> {
564	    let claimed = decision
565	        .entries
566	        .iter()
567	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
568	        .collect::<std::collections::BTreeMap<_, _>>();
569	
570	    let changed_paths = changed
571	        .iter()
572	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
573	        .collect::<std::collections::BTreeSet<_>>();
574	
575	    // Both traversals walk `packages()` and `canonical_manifests()` in the same ordered storage, so batched results zip back by position.
576	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
577	        .graph
578	        .packages()
579	        .flat_map(Package::canonical_manifests)
580	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
581	        .collect::<Result<_, GraphError>>()?;
582	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
583	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
584	    for (path, _) in manifest_queries
585	        .iter()
586	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
587	    {
588	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
589	        {
590	            let candidate = normalized_git_path(&candidate)?;
591	            if !query_path_list.contains(&candidate) {
592	                query_path_list.push(candidate);
593	            }
594	        }
595	    }
596	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
597	
598	    // Exactly two `git cat-file --batch` invocations in all (one per commit), however many canonical manifests the
599	    // workspace has.
600	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, parent, &query_paths)?;
601	    let after_blobs =
602	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
603	    let before = CommitBlobs::new(workspace.runner, &workspace.root, parent, &query_paths, before_blobs);
604	    let after = CommitBlobs::new(
605	        workspace.runner,
606	        &workspace.root,
607	        release_commit.as_str(),
608	        &query_paths,
609	        after_blobs,
610	    );
611	    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
612	    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;
613	
614	    let mut observed = std::collections::BTreeSet::new();
615	    let mut manifest_index = 0usize;
616	    for package in workspace.graph.packages() {
617	        let package_ids = release_package_ids(&workspace.identity, package)?;
618	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
619	        if package_is_claimed {
620	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
621	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
622	            })?;
623	            let changelog = normalized_git_path(changelog)?;
624	            if !changed_paths.contains(changelog.as_str()) {
625	                return Err(GraphError::ReleaseCommitVerificationFailed {
626	                    commit: release_commit.clone(),
627	                    reason: CommitVerificationFailure::ChangelogNotTouched,
628	                });
629	            }
630	        }
631	        for id in package_ids {
632	            let before = &before_versions[manifest_index];
633	            let after = &after_versions[manifest_index];
634	            manifest_index += 1;
635	            let changed_version = before.version != after.version;
636	            match claimed.get(&id) {
637	                Some(target_version) => {
638	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
639	                        return Err(GraphError::ReleaseCommitVerificationFailed {
640	                            commit: release_commit.clone(),
641	                            reason: CommitVerificationFailure::ManifestNotInDiff,
642	                        });
643	                    }
644	                    if !changed_version || &after.version != target_version {
645	                        return Err(GraphError::ReleaseCommitVerificationFailed {
646	                            commit: release_commit.clone(),
647	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
648	                        });
649	                    }
650	                    observed.insert(id);
651	                }
652	                None => {
653	                    if changed_version {
654	                        // A changed version the committed decision never
655	                        // claimed is not this commit's authority -- fail
656	                        // closed rather than trust a partial match.
657	                        return Err(GraphError::ReleaseCommitVerificationFailed {
658	                            commit: release_commit.clone(),
659	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
660	                        });
661	                    }
662	                }
663	            }
664	        }
665	    }
666	    if observed.len() != claimed.len() {
667	        return Err(GraphError::ReleaseCommitVerificationFailed {
668	            commit: release_commit.clone(),
669	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
670	        });
671	    }
672	    Ok(())
673	}
