692	/// Whether a version commit may change `path`: a manifest or lockfile anywhere, a package's changelog, the decision
693	/// file, a changeset, or the changesets directory's `pre.json`.
694	fn is_version_commit_path(
695	    path: &str,
696	    decision_path: &str,
697	    changeset_dir: &str,
698	    changelogs: &std::collections::BTreeSet<String>,
699	) -> bool {
700	    let file_name = path.rsplit('/').next().unwrap_or(path);
701	    let pre_json = if changeset_dir.is_empty() {
702	        "pre.json".to_owned()
703	    } else {
704	        format!("{changeset_dir}/pre.json")
705	    };
706	    path == decision_path
707	        || path == pre_json
708	        || VERSION_MANIFESTS.contains(&file_name)
709	        || VERSION_LOCKFILES.contains(&file_name)
710	        || changelogs.contains(path)
711	        || is_changeset_path(path, changeset_dir)
712	}
713	
714	fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
715	    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
716	        if changeset_dir.is_empty() {
717	            Some(path)
718	        } else {
719	            path.strip_prefix('/')
720	        }
721	    }) else {
722	        return false;
723	    };
724	
725	    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
726	}
