764	fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
765	    output
766	        .lines()
767	        .map(|line| {
768	            let (status, path) = line.split_once('\t').ok_or_else(|| {
769	                command_malformed_output(
770	                    "git",
771	                    args,
772	                    format!("name-status line missing a tab separator: `{line}`"),
773	                )
774	            })?;
775	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
776	                return Err(command_malformed_output(
777	                    "git",
778	                    args,
779	                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
780	                ));
781	            }
782	            Ok((status.to_string(), path.to_string()))
783	        })
784	        .collect()
785	}
