862	/// The manifests of one commit: those fetched up front in one batch, and any other fetched on first ask. A package that
863	/// names its workspace with `package.workspace` can name a different one at each of two commits, so the second commit's
864	/// workspace manifest is not among those fetched for the first.
865	struct CommitBlobs<'a, R: CommandRunner> {
866	    runner: &'a R,
867	    root: &'a std::path::Path,
868	    commit: &'a str,
869	    blobs: std::cell::RefCell<std::collections::BTreeMap<String, BatchBlob>>,
870	}
871	
872	impl<'a, R: CommandRunner> CommitBlobs<'a, R> {
873	    fn new(runner: &'a R, root: &'a std::path::Path, commit: &'a str, paths: &[&str], blobs: Vec<BatchBlob>) -> Self {
874	        CommitBlobs {
875	            runner,
876	            root,
877	            commit,
878	            blobs: std::cell::RefCell::new(paths.iter().map(|path| (*path).to_owned()).zip(blobs).collect()),
879	        }
880	    }
881	
882	    /// The text of `path` at the commit, `None` when it has none there.
883	    fn text(&self, path: &str) -> Result<Option<String>, GraphError> {
884	        if !self.blobs.borrow().contains_key(path) {
885	            let fetched = batch_manifest_blobs_at(self.runner, self.root, self.commit, &[path])?;
886	            let blob = fetched.into_iter().next().unwrap_or(BatchBlob::Missing);
887	            self.blobs.borrow_mut().insert(path.to_owned(), blob);
888	        }
889	        Ok(match &self.blobs.borrow()[path] {
890	            BatchBlob::Blob(text) => Some(text.clone()),
891	            BatchBlob::Missing => None,
892	        })
893	    }
894	}
