896	fn resolve_batch_versions<R: CommandRunner>(
897	    commit: &CommitBlobs<'_, R>,
898	    queries: &[(String, Ecosystem)],
899	) -> Result<Vec<callisto_manifests::EffectiveManifestVersion>, GraphError> {
900	    let mut reads = callisto_manifests::WorkspaceReads::default();
901	    let at_commit = |other: &std::path::Path| -> Result<Option<String>, callisto_model::ManifestError> {
902	        let unavailable = |message: String| callisto_model::ManifestError::Read {
903	            path: other.to_path_buf(),
904	            message,
905	        };
906	        let key = normalized_git_path(other).map_err(|error| unavailable(error.to_string()))?;
907	        commit.text(&key).map_err(|error| unavailable(error.to_string()))
908	    };
909	    queries
910	        .iter()
911	        .map(|(path, ecosystem)| {
912	            let Some(source) = commit.text(path)? else {
913	                return Err(command_malformed_output(
914	                    "git",
915	                    &["cat-file", "--batch"],
916	                    format!("canonical manifest `{path}` was reported missing at the queried commit"),
917	                ));
918	            };
919	            let format = ecosystem
920	                .canonical_manifest_format()
921	                .ok_or_else(|| GraphError::ReleaseInvariant {
922	                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
923	                })?;
924	            callisto_manifests::read_effective_version(
925	                format,
926	                &source,
927	                std::path::Path::new(path),
928	                &mut reads,
929	                at_commit,
930	            )
931	            .map_err(historical_manifest_error)?
932	            .ok_or_else(|| {
933	                command_malformed_output(
934	                    "git",
935	                    &["cat-file", "--batch"],
936	                    format!("manifest `{path}` has no effective declared version"),
937	                )
938	            })
939	        })
940	        .collect()
941	}
