943	/// The distribution of `via` that `dependent`'s matching edges name, in `entry`'s ecosystem when they name several.
944	fn cascade_source<D: DependencyResolver>(
945	    graph: &D,
946	    dependent: &callisto_model::PackageId,
947	    via: &callisto_model::PackageId,
948	    entry: &ReleasePackageId,
949	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
950	    edge_matches: impl Fn(&callisto_model::DepEdge) -> bool,
951	) -> Option<ReleasePackageId> {
952	    let ids = package_ids.get(via)?;
953	    if let [only] = ids.as_slice() {
954	        return Some(only.clone());
955	    }
956	    let ecosystems: std::collections::BTreeSet<Ecosystem> = graph
957	        .dependencies_of(dependent)
958	        .filter(|edge| edge.to == *via && edge_matches(edge))
959	        .map(|edge| crate::cascade::manifest_ecosystem(&edge.from_manifest))
960	        .collect();
961	    let candidates: Vec<&ReleasePackageId> = ids.iter().filter(|id| ecosystems.contains(&id.ecosystem())).collect();
962	    candidates
963	        .iter()
964	        .find(|id| id.ecosystem() == entry.ecosystem())
965	        .or(match candidates.as_slice() {
966	            [only] => Some(only),
967	            _ => None,
968	        })
969	        .map(|id| (*id).clone())
970	}
