972	fn reason_from_bump<D: DependencyResolver>(
973	    graph: &D,
974	    dependent: &callisto_model::PackageId,
975	    entry: &ReleasePackageId,
976	    reason: Option<&BumpReason>,
977	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
978	) -> Result<ReleaseInclusionReason, GraphError> {
979	    match reason {
980	        Some(BumpReason::Changeset { .. }) => Ok(ReleaseInclusionReason::Changeset),
981	        // Every planned bump comes from a seed or a cascade step, both of which carry a reason.
982	        None => Err(GraphError::ReleaseInvariant {
983	            detail: format!("planned bump for `{}` has no reason", dependent.display_name()),
984	        }),
985	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
986	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
987	            group_id: group.to_string(),
988	        }),
989	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
990	            Ok(ReleaseInclusionReason::FixedGroup {
991	                group_id: group.to_string(),
992	            })
993	        }
994	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
995	        Some(BumpReason::Cascade {
996	            via, dep_kind, spec, ..
997	        }) => {
998	            // The plan and edges share one workspace graph, so a miss is a broken pairing, not an operator error.
999	            let source = cascade_source(graph, dependent, via, entry, package_ids, |edge| {
1000	                edge.kind == *dep_kind && edge.spec.render() == *spec
1001	            })
1002	            .ok_or_else(|| GraphError::ReleaseInvariant {
1003	                detail: format!(
1004	                    "cascade source package `{}` has no release package id that `{entry}` unambiguously depends on",
1005	                    via.display_name()
1006	                ),
1007	            })?;
1008	            Ok(ReleaseInclusionReason::Cascade {
1009	                from: source,
1010	                edge_kind: format!("{dep_kind:?}"),
1011	            })
1012	        }
1013	        Some(BumpReason::PeerEscalation { via, spec }) => {
1014	            let source = cascade_source(graph, dependent, via, entry, package_ids, |edge| {
1015	                edge.kind == callisto_model::DepKind::Peer && edge.spec.render() == *spec
1016	            })
1017	            .ok_or_else(|| GraphError::ReleaseInvariant {
1018	                detail: format!(
1019	                    "peer-escalation source package `{}` has no release package id that `{entry}` unambiguously \
1020	                     depends on",
1021	                    via.display_name()
1022	                ),
1023	            })?;
1024	            Ok(ReleaseInclusionReason::Cascade {
1025	                from: source,
1026	                edge_kind: "peer".to_string(),
1027	            })
1028	        }
1029	        Some(_) => Err(GraphError::UnsupportedRelease {
1030	            feature: UnsupportedReleaseFeature::BumpReason,
1031	        }),
1032	    }
1033	}
