//! Deterministic, graph-owned release roster decisions.
//!
//! It records the exact package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use super::git_batch::{batch_blobs, BatchBlob};
use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` derives from this observation, so a missing package id means an inconsistent pairing, not an operator error.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(
                    &workspace.graph,
                    &bump.package,
                    id,
                    bump.reason.as_ref(),
                    &package_ids,
                )?],
            });
        }
    }
    let consumed = plan
        .consumed_changesets
        .iter()
        .map(|path| normalized_git_path(path))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(ReleaseDecisionV1::new(entries)?.consuming(consumed))
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    let owners = ReleaseOwners::of(workspace);
    let released = complete
        .entries
        .iter()
        .map(|entry| &entry.package)
        .collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = owners.get(selection) else {
            let missing = callisto_model::PackageId::Prefixed {
                ecosystem: selection.ecosystem(),
                name: selection.name().to_string(),
            };
            return Err(GraphError::unknown_package(
                missing,
                workspace.graph.packages().map(Package::canonical_id),
            ));
        };
        let reason = if !released.contains(*selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, &owners, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    owners: &ReleaseOwners<'_>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, owners, selection))
        .collect::<std::collections::BTreeSet<_>>();
    // Selecting one distribution of a package releases all of them, so the shared tag waits for every publish.
    let selected_packages = selected
        .iter()
        .filter_map(|selection| owners.get(selection))
        .map(|package| package.id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || owners.get(&entry.package).is_some_and(|package| selected_packages.contains(&package.id))
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, owners, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has no tag in the canonical
/// [`crate::TagIndex`], each with [`ReleaseInclusionReason::UnreleasedVersion`], and keeps the tagged releases in
/// `resumable`: a tag does not prove the rest of the release was observed.
///
/// A non-empty `selections` restricts the roster to exactly those identities, each of which must be unreleased and
/// publishable. `None` means nothing is unreleased.
pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
    resumable: &std::collections::BTreeSet<ReleasePackageId>,
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        let ids = release_package_ids(&workspace.identity, package)?;
        if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
            continue;
        }
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    let owners = ReleaseOwners::of(workspace);
    let unreleased = entries
        .iter()
        .map(|entry| entry.package.clone())
        .collect::<std::collections::BTreeSet<_>>();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = owners.get(selection) else {
            let missing = callisto_model::PackageId::Prefixed {
                ecosystem: selection.ecosystem(),
                name: selection.name().to_string(),
            };
            return Err(GraphError::unknown_package(
                missing,
                workspace.graph.packages().map(Package::canonical_id),
            ));
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !unreleased.contains(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, &owners, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> bool {
    tag_of_version(tags, package, version).is_some()
}

pub(crate) fn tag_of_version(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> Option<String> {
    let rendered = tags.template(package).render(version).to_string();
    if tags.is_tag_of(package, &rendered) {
        return Some(rendered);
    }
    tags.last_tag(package)
        .filter(|tag| &tag.version == version)
        .map(|tag| tag.name.to_string())
}

/// Entries for every publishable package whose current version is tagged on `source`.
///
/// A run that created such a tag may have stopped before pushing it or finishing the release.
pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    source: &CommitSha,
) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let git = workspace.git_access();
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let Some(version) = versions.get(&package.id) else {
            continue;
        };
        // Only the tag this run's tag operation would create: one made under an older template is another release's.
        let tag = tags.template(&package.id).render(version).to_string();
        if !tags.contains_tag(&tag) {
            continue;
        }
        if tags.commit_of(git, &tag)?.as_ref() != Some(source) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }
    Ok(entries)
}

pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
    package
        .publish_to
        .iter()
        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
}

/// Each release identity's workspace package, built once so a lookup per entry does not rescan every package.
pub(crate) struct ReleaseOwners<'w>(std::collections::BTreeMap<ReleasePackageId, &'w Package>);

impl<'w> ReleaseOwners<'w> {
    pub(crate) fn of<R: callisto_model::CommandRunner, D: DependencyResolver>(
        workspace: &'w Workspace<'_, R, D>,
    ) -> Self {
        let mut owners = std::collections::BTreeMap::new();
        // By release identity, not name: a dual-manifest package's npm name can differ from its id.
        for package in workspace.graph.packages() {
            for id in release_package_ids(&workspace.identity, package).unwrap_or_default() {
                owners.entry(id).or_insert(package);
            }
        }
        Self(owners)
    }

    /// The workspace package with this exact release identity.
    pub(crate) fn get(&self, id: &ReleasePackageId) -> Option<&'w Package> {
        self.0.get(id).copied()
    }
}

/// The fixed and linked groups a release package belongs to, per config.
fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    owners: &ReleaseOwners<'_>,
    id: &ReleasePackageId,
) -> Vec<(&'static str, callisto_model::GroupName)> {
    let Some(package) = owners.get(id) else {
        return Vec::new();
    };
    let groups = &workspace.config.groups;
    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
    // Member keys are canonical, so compare exactly; `PackageId::matches` would treat a Bare key as an ecosystem wildcard.
    fixed
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy here from raw git diffs would duplicate logic that drifts (it would miss, for
/// instance, a fixed-group cascade that touches an unnamed sibling), so this function reads the committed
/// decision back and confirms the commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let (parent, changed) = commit_delta(workspace, release_commit)?;
    let decision_path_str = normalized_git_path(decision_path)?;
    require_version_commit_shape(workspace, release_commit, &changed, &decision_path_str)?;
    let decision = read_committed_decision(workspace, release_commit, decision_path, &decision_path_str)?;
    require_recorded_changesets_consumed(workspace, release_commit, &changed, &decision)?;
    require_manifests_match_decision(workspace, release_commit, &parent, &changed, &decision)?;
    Ok(decision)
}

/// The commit's parent and what the commit changed against it, as `(status, path)` pairs. Fails unless `HEAD` is the
/// release commit.
fn commit_delta<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
) -> Result<(String, Vec<(String, String)>), GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let mut changed = parse_name_status(&changed, &diff_tree_args)?;

    // `diff-tree` paths are repository-top-relative. Rewrite them workspace-relative; an edit outside the workspace
    // becomes `../..` so it never matches a workspace path and is still refused as unexpected.
    let prefix = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "--show-prefix"])?;
    let up = "../".repeat(prefix.matches('/').count());
    for (_, path) in &mut changed {
        *path = match path.strip_prefix(prefix.as_str()) {
            Some(inside) => inside.to_owned(),
            None => format!("{up}{path}"),
        };
    }
    Ok((parent, changed))
}

/// The commit has the shape of a version commit: it wrote the decision and touched only the paths a version commit may
/// touch.
fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    changed: &[(String, String)],
    decision_path: &str,
) -> Result<(), GraphError> {
    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;

    // The decision must be written by this commit, not left over from an earlier release.
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
    // or where, under the cover of a bot-authored diff.
    let changelogs = workspace
        .graph
        .packages()
        .filter_map(|package| package.changelog.as_deref())
        .map(normalized_git_path)
        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
    for (_, path) in changed {
        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
            return Err(GraphError::ReleaseCommitVerificationFailed {
                commit: release_commit.clone(),
                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
            });
        }
    }
    Ok(())
}

/// The commit deletes exactly the changesets the decision recorded. A decision from before that record must delete at
/// least one, since every release then started from a changeset.
fn require_recorded_changesets_consumed<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    changed: &[(String, String)],
    decision: &ReleaseDecisionV1,
) -> Result<(), GraphError> {
    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
    let deleted: std::collections::BTreeSet<&str> = changed
        .iter()
        .filter(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir))
        .map(|(_, path)| path.as_str())
        .collect();
    let consumed_as_recorded = match &decision.consumed_changesets {
        Some(recorded) => recorded.iter().map(String::as_str).eq(deleted.iter().copied()),
        None => !deleted.is_empty(),
    };
    if !consumed_as_recorded {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ConsumedChangesetsDiffer,
        });
    }
    Ok(())
}

/// The decision file as the release commit holds it. Its own deserializer rejects entries that do not match its digest.
fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
    decision_path_str: &str,
) -> Result<ReleaseDecisionV1, GraphError> {
    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        decision_path_str,
    )?;
    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
        path: decision_path.to_path_buf(),
        message: error.to_string(),
    })
}

/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
/// no package the decision does not claim changed version.
fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    parent: &str,
    changed: &[(String, String)],
    decision: &ReleaseDecisionV1,
) -> Result<(), GraphError> {
    let claimed = decision
        .entries
        .iter()
        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();

    let changed_paths = changed
        .iter()
        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
        .collect::<std::collections::BTreeSet<_>>();

    // Both traversals walk `packages()` and `canonical_manifests()` in the same ordered storage, so batched results zip back by position.
    let manifest_queries: Vec<(String, Ecosystem)> = workspace
        .graph
        .packages()
        .flat_map(Package::canonical_manifests)
        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
        .collect::<Result<_, GraphError>>()?;
    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
    for (path, _) in manifest_queries
        .iter()
        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
    {
        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
        {
            let candidate = normalized_git_path(&candidate)?;
            if !query_path_list.contains(&candidate) {
                query_path_list.push(candidate);
            }
        }
    }
    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();

    // Exactly two `git cat-file --batch` invocations in all (one per commit), however many canonical manifests the
    // workspace has.
    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, parent, &query_paths)?;
    let after_blobs =
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before = CommitBlobs::new(workspace.runner, &workspace.root, parent, &query_paths, before_blobs);
    let after = CommitBlobs::new(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &query_paths,
        after_blobs,
    );
    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            let changelog = normalized_git_path(changelog)?;
            if !changed_paths.contains(changelog.as_str()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for id in package_ids {
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before.version != after.version;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || &after.version != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });
                    }
                }
            }
        }
    }
    if observed.len() != claimed.len() {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
        });
    }
    Ok(())
}

/// The manifests Callisto writes versions and dependency ranges into.
const VERSION_MANIFESTS: &[&str] = &["Cargo.toml", "package.json", "pyproject.toml"];

/// The lockfiles Callisto refreshes after it writes versions.
const VERSION_LOCKFILES: &[&str] = &[
    "Cargo.lock",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
    "uv.lock",
    "poetry.lock",
    "pdm.lock",
];

/// Whether a version commit may change `path`: a manifest or lockfile anywhere, a package's changelog, the decision
/// file, a changeset, or the changesets directory's `pre.json`.
fn is_version_commit_path(
    path: &str,
    decision_path: &str,
    changeset_dir: &str,
    changelogs: &std::collections::BTreeSet<String>,
) -> bool {
    let file_name = path.rsplit('/').next().unwrap_or(path);
    let pre_json = if changeset_dir.is_empty() {
        "pre.json".to_owned()
    } else {
        format!("{changeset_dir}/pre.json")
    };
    path == decision_path
        || path == pre_json
        || VERSION_MANIFESTS.contains(&file_name)
        || VERSION_LOCKFILES.contains(&file_name)
        || changelogs.contains(path)
        || is_changeset_path(path, changeset_dir)
}

fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
        if changeset_dir.is_empty() {
            Some(path)
        } else {
            path.strip_prefix('/')
        }
    }) else {
        return false;
    };

    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
/// exited non-zero, carrying its real exit status and stderr instead of
/// discarding them.
pub(super) fn command_non_zero_exit(
    program: &str,
    args: &[&str],
    output: &callisto_model::CommandOutput,
) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: output.exit_code,
            stderr: output.stderr.clone(),
        },
    }
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
/// output could not be parsed into the shape this module expects.
pub(super) fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::MalformedOutput { detail: detail.into() },
    }
}

fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
    let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
    if !output.success() {
        return Err(command_non_zero_exit("git", args, &output));
    }
    Ok(output.stdout_trimmed().to_string())
}

fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
    output
        .lines()
        .map(|line| {
            let (status, path) = line.split_once('\t').ok_or_else(|| {
                command_malformed_output(
                    "git",
                    args,
                    format!("name-status line missing a tab separator: `{line}`"),
                )
            })?;
            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
                return Err(command_malformed_output(
                    "git",
                    args,
                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
                ));
            }
            Ok((status.to_string(), path.to_string()))
        })
        .collect()
}

fn git_file<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    path: &str,
) -> Result<String, GraphError> {
    let object = object_at(commit, path);
    git_stdout(runner, root, &["show", &object])
}

/// `rev:./path`: git resolves a bare `rev:path` from the repository top, not the workspace directory.
pub(super) fn object_at(rev: &str, path: &str) -> String {
    format!("{rev}:./{path}")
}

pub(super) fn normalized_git_path(path: &std::path::Path) -> Result<String, GraphError> {
    let path = callisto_model::workspace_relative(path)?;
    let path = path.to_string_lossy().into_owned();
    if path.contains(['\0', '\n', '\r']) {
        return Err(command_malformed_output(
            "git",
            &["cat-file", "--batch"],
            "workspace path contains a forbidden control character",
        ));
    }
    Ok(path)
}

fn historical_manifest_error(error: callisto_model::ManifestError) -> GraphError {
    match error {
        callisto_model::ManifestError::InvalidVersion { source, .. } => GraphError::from(source),
        other => command_malformed_output("git", &["cat-file", "--batch"], other.to_string()),
    }
}

#[cfg(test)]
fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
    // `canonical_manifests()` only builds Canonical decls for formats that have a canonical format; a miss breaks that invariant.
    let format = ecosystem
        .canonical_manifest_format()
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!(
                "canonical manifest `{path}` has ecosystem `{}`, which has no canonical manifest format",
                ecosystem.prefix()
            ),
        })?;
    let version = callisto_manifests::read_effective_version(
        format,
        source,
        std::path::Path::new(path),
        &mut callisto_manifests::WorkspaceReads::default(),
        |_| Ok::<_, callisto_model::ManifestError>(None),
    )
    .map_err(historical_manifest_error)?
    .ok_or_else(|| {
        command_malformed_output(
            "git",
            &["cat-file", "--batch"],
            format!("manifest `{path}` has no effective declared version"),
        )
    })?;
    Ok(version.version)
}

/// Every path in `paths` at `commit`, in one `git cat-file --batch`.
fn batch_manifest_blobs_at<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    paths: &[&str],
) -> Result<Vec<BatchBlob>, GraphError> {
    let objects: Vec<String> = paths.iter().map(|path| object_at(commit, path)).collect();
    batch_blobs(runner, root, &objects)
}

/// The manifests of one commit: those fetched up front in one batch, and any other fetched on first ask. A package that
/// names its workspace with `package.workspace` can name a different one at each of two commits, so the second commit's
/// workspace manifest is not among those fetched for the first.
struct CommitBlobs<'a, R: CommandRunner> {
    runner: &'a R,
    root: &'a std::path::Path,
    commit: &'a str,
    blobs: std::cell::RefCell<std::collections::BTreeMap<String, BatchBlob>>,
}

impl<'a, R: CommandRunner> CommitBlobs<'a, R> {
    fn new(runner: &'a R, root: &'a std::path::Path, commit: &'a str, paths: &[&str], blobs: Vec<BatchBlob>) -> Self {
        CommitBlobs {
            runner,
            root,
            commit,
            blobs: std::cell::RefCell::new(paths.iter().map(|path| (*path).to_owned()).zip(blobs).collect()),
        }
    }

    /// The text of `path` at the commit, `None` when it has none there.
    fn text(&self, path: &str) -> Result<Option<String>, GraphError> {
        if !self.blobs.borrow().contains_key(path) {
            let fetched = batch_manifest_blobs_at(self.runner, self.root, self.commit, &[path])?;
            let blob = fetched.into_iter().next().unwrap_or(BatchBlob::Missing);
            self.blobs.borrow_mut().insert(path.to_owned(), blob);
        }
        Ok(match &self.blobs.borrow()[path] {
            BatchBlob::Blob(text) => Some(text.clone()),
            BatchBlob::Missing => None,
        })
    }
}

fn resolve_batch_versions<R: CommandRunner>(
    commit: &CommitBlobs<'_, R>,
    queries: &[(String, Ecosystem)],
) -> Result<Vec<callisto_manifests::EffectiveManifestVersion>, GraphError> {
    let mut reads = callisto_manifests::WorkspaceReads::default();
    let at_commit = |other: &std::path::Path| -> Result<Option<String>, callisto_model::ManifestError> {
        let unavailable = |message: String| callisto_model::ManifestError::Read {
            path: other.to_path_buf(),
            message,
        };
        let key = normalized_git_path(other).map_err(|error| unavailable(error.to_string()))?;
        commit.text(&key).map_err(|error| unavailable(error.to_string()))
    };
    queries
        .iter()
        .map(|(path, ecosystem)| {
            let Some(source) = commit.text(path)? else {
                return Err(command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("canonical manifest `{path}` was reported missing at the queried commit"),
                ));
            };
            let format = ecosystem
                .canonical_manifest_format()
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
                })?;
            callisto_manifests::read_effective_version(
                format,
                &source,
                std::path::Path::new(path),
                &mut reads,
                at_commit,
            )
            .map_err(historical_manifest_error)?
            .ok_or_else(|| {
                command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("manifest `{path}` has no effective declared version"),
                )
            })
        })
        .collect()
}

/// The distribution of `via` that `dependent`'s matching edges name, in `entry`'s ecosystem when they name several.
fn cascade_source<D: DependencyResolver>(
    graph: &D,
    dependent: &callisto_model::PackageId,
    via: &callisto_model::PackageId,
    entry: &ReleasePackageId,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
    edge_matches: impl Fn(&callisto_model::DepEdge) -> bool,
) -> Option<ReleasePackageId> {
    let ids = package_ids.get(via)?;
    if let [only] = ids.as_slice() {
        return Some(only.clone());
    }
    let ecosystems: std::collections::BTreeSet<Ecosystem> = graph
        .dependencies_of(dependent)
        .filter(|edge| edge.to == *via && edge_matches(edge))
        .map(|edge| crate::cascade::manifest_ecosystem(&edge.from_manifest))
        .collect();
    let candidates: Vec<&ReleasePackageId> = ids.iter().filter(|id| ecosystems.contains(&id.ecosystem())).collect();
    candidates
        .iter()
        .find(|id| id.ecosystem() == entry.ecosystem())
        .or(match candidates.as_slice() {
            [only] => Some(only),
            _ => None,
        })
        .map(|id| (*id).clone())
}

fn reason_from_bump<D: DependencyResolver>(
    graph: &D,
    dependent: &callisto_model::PackageId,
    entry: &ReleasePackageId,
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) => Ok(ReleaseInclusionReason::Changeset),
        // Every planned bump comes from a seed or a cascade step, both of which carry a reason.
        None => Err(GraphError::ReleaseInvariant {
            detail: format!("planned bump for `{}` has no reason", dependent.display_name()),
        }),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),
        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
            Ok(ReleaseInclusionReason::FixedGroup {
                group_id: group.to_string(),
            })
        }
        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
        Some(BumpReason::Cascade {
            via, dep_kind, spec, ..
        }) => {
            // The plan and edges share one workspace graph, so a miss is a broken pairing, not an operator error.
            let source = cascade_source(graph, dependent, via, entry, package_ids, |edge| {
                edge.kind == *dep_kind && edge.spec.render() == *spec
            })
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "cascade source package `{}` has no release package id that `{entry}` unambiguously depends on",
                    via.display_name()
                ),
            })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: format!("{dep_kind:?}"),
            })
        }
        Some(BumpReason::PeerEscalation { via, spec }) => {
            let source = cascade_source(graph, dependent, via, entry, package_ids, |edge| {
                edge.kind == callisto_model::DepKind::Peer && edge.spec.render() == *spec
            })
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "peer-escalation source package `{}` has no release package id that `{entry}` unambiguously \
                     depends on",
                    via.display_name()
                ),
            })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: "peer".to_string(),
            })
        }
        Some(_) => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::BumpReason,
        }),
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Ecosystem, Version};

    use super::*;

    #[test]
    fn decision_is_canonical_and_ecosystem_qualified() {
        let cargo = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let npm = ReleasePackageId::new(Ecosystem::Npm, "demo").unwrap();
        let first = ReleaseDecisionV1::new(vec![
            ReleaseDecisionEntry {
                package: npm,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
            ReleaseDecisionEntry {
                package: cargo,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
        ])
        .unwrap();
        assert_eq!(first.entries[0].package.to_string(), "cargo/demo");
        assert_ne!(first.entries[0].package, first.entries[1].package);
    }

    #[test]
    fn release_commit_delta_parser_accepts_only_unambiguous_path_statuses() {
        let args = ["diff-tree", "--name-status"];
        assert_eq!(
            parse_name_status("M\tCargo.toml\nD\t.changeset/release.md\n", &args).unwrap(),
            vec![
                ("M".to_string(), "Cargo.toml".to_string()),
                ("D".to_string(), ".changeset/release.md".to_string()),
            ]
        );
        assert!(parse_name_status("R100\told\tnew\n", &args).is_err());
        assert!(parse_name_status("M Cargo.toml\n", &args).is_err());
    }

    #[test]
    fn changeset_path_matches_only_direct_child_markdown_files() {
        assert!(is_changeset_path(".changeset/release.md", ".changeset"));
        assert!(!is_changeset_path(".changeset/README.md", ".changeset"));
        assert!(!is_changeset_path(".changeset/nested/release.md", ".changeset"));
        assert!(!is_changeset_path(".changesets/release.md", ".changeset"));
    }

    #[test]
    fn root_changeset_dir_matches_only_root_level_markdown_files() {
        assert!(is_changeset_path("release.md", ""));
        assert!(!is_changeset_path("README.md", ""));
        assert!(!is_changeset_path("docs/notes.md", ""));
        assert!(!is_changeset_path("nested/release.md", ""));
    }

    /// Both malformed name-status lines surface as `GraphError::ReleaseCommand` (E164) with a
    /// `CommandFailure::MalformedOutput` cause naming the real `git` program and args.
    #[test]
    fn release_commit_delta_parser_reports_malformed_output_not_stale_intent() {
        let args = ["diff-tree", "--name-status"];
        let err = parse_name_status("R100\told\tnew\n", &args).unwrap_err();
        match err {
            GraphError::ReleaseCommand {
                program,
                failure: CommandFailure::MalformedOutput { .. },
                ..
            } => assert_eq!(program, "git"),
            other => panic!("expected ReleaseCommand{{failure: MalformedOutput}}, got {other:?}"),
        }
    }

    struct FixedBlobRunner(&'static str);

    impl CommandRunner for FixedBlobRunner {
        fn run(
            &self,
            _program: &str,
            _args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            Ok(callisto_model::CommandOutput {
                exit_code: Some(0),
                stdout: self.0.to_string(),
                stderr: String::new(),
            })
        }
    }

    /// Test-only: single-object equivalent of the batched
    /// `git cat-file --batch` path production code now uses (see
    /// `batch_manifest_blobs_at`/`resolve_batch_versions`), kept only so
    /// the two tests below can exercise `parse_manifest_version`'s parsing
    /// rules through a `CommandRunner` + single `git show` fetch, matching
    /// how a plain manifest read works.
    fn manifest_version_at<R: CommandRunner>(
        runner: &R,
