1	//! Interface for typed managed release-pull-request decisions, and for
2	//! building the exact forge commit-API file changes the executor submits.
3	//! `decide` and `verify` are read-only; `commit-plan` reads the Git index
4	//! and worktree but writes no forge state itself -- the executor script is
5	//! the only thing that ever calls GitHub.
6	
7	use std::process::ExitCode;
8	
9	use callisto_graph::commands::{plan_version, VersionOptions};
10	use callisto_graph::resolver::ManifestWalkResolver;
11	use callisto_graph::{GraphError, Workspace};
12	use callisto_model::format::{parse_pre_json, PreMode};
13	use callisto_model::vcs::GitAccess;
14	use callisto_model::{
15	    CommitSha, GitHubRepository, ReleasePrActionV2, ReleasePrCommitPlanReport, ReleasePrCommitPlanV1,
16	    ReleasePrConfigV1, ReleasePrConfigWireV1, ReleasePrDecideReport, ReleasePrDecisionError, ReleasePrDecisionV2,
17	    ReleasePrDecisionWireV2, ReleasePrSnapshotV2, ReleasePrSnapshotWireV2, ReleasePrVerifyReport,
18	};
19	
20	use crate::cli::{
21	    GlobalArgs, OutputFormat, ReleasePrArgs, ReleasePrCommitPlanArgs, ReleasePrDecideArgs, ReleasePrVerifyArgs,
22	};
23	use crate::error::CliError;
24	use crate::io::{read_json_input, OutputFile, OutputKind};
25	use crate::output::{emit_line, emit_report};
26	use crate::runner::CliCommandRunner;
27	use crate::workspace::load_workspace;
28	
29	pub fn handle(args: ReleasePrArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
30	    match args {
31	        ReleasePrArgs::Decide(args) => decide(args, global),
32	        ReleasePrArgs::Verify(args) => verify(args, global),
33	        ReleasePrArgs::CommitPlan(args) => commit_plan(args, global),
34	    }
35	}
36	
37	#[derive(serde::Deserialize)]
38	#[serde(rename_all = "camelCase", deny_unknown_fields)]
39	struct ReleasePrDecisionInput {
40	    schema_version: u8,
41	    config: ReleasePrConfigWireV1,
42	    snapshot: ReleasePrSnapshotWireV2,
43	    action: ReleasePrActionV2,
44	    #[serde(default, deserialize_with = "deserialize_present")]
45	    command: Option<String>,
46	    #[serde(default, deserialize_with = "deserialize_present")]
47	    dry_run: Option<bool>,
48	}
49	
50	// Missing report metadata is allowed, but present null values are not.
51	fn deserialize_present<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
52	where
53	    D: serde::Deserializer<'de>,
54	    T: serde::Deserialize<'de>,
55	{
56	    T::deserialize(deserializer).map(Some)
57	}
58	
59	fn read_decision_arg(arg: &str) -> Result<ReleasePrDecisionWireV2, CliError> {
60	    let input: ReleasePrDecisionInput = read_json_input("decision", arg)?;
61	    match (&input.command, input.dry_run) {
62	        (None, None) => {}
63	        (Some(command), Some(_)) if command == <ReleasePrDecideReport as callisto_model::Report>::COMMAND => {}
64	        _ => {
65	            return Err(CliError::ReleasePrArgJsonInvalid {
66	                flag: "decision",
67	                detail: "report metadata must include command=\"release-pr decide\" and a boolean dryRun".into(),
68	            });
69	        }
70	    }
71	    Ok(ReleasePrDecisionWireV2 {
72	        schema_version: input.schema_version,
73	        config: input.config,
74	        snapshot: input.snapshot,
75	        action: input.action,
76	    })
77	}
78	
79	fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
80	    let decision_wire = read_decision_arg(&args.decision)?;
81	    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
82	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_input("snapshot", &args.snapshot)?;
83	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
84	    match args.applied_head {
85	        Some(head) => decision.verify_snapshot_after_update(&snapshot, &CommitSha::parse(&head)?)?,
86	        None => decision.verify_snapshot(&snapshot)?,
87	    }
88	    match global.format {
89	        OutputFormat::Json => emit_report(
90	            &mut std::io::stdout(),
91	            &ReleasePrVerifyReport { ok: true },
92	            global.dry_run,
93	        )?,
94	        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
95	    }
96	    Ok(ExitCode::SUCCESS)
97	}
98	
99	fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
100	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_input("snapshot", &args.snapshot)?;
101	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
102	    let repository =
103	        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
104	            repository: args.repository.clone(),
105	        })?;
106	    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;
107	
108	    let runner = CliCommandRunner;
109	    let workspace = load_workspace(global, &runner)?;
110	    reject_pre_mode(&workspace)?;
111	    let inference = crate::workspace::select_inference();
112	    // The plan `version` would apply, so an unparseable changeset fails here instead of looking like nothing pending.
113	    let options = VersionOptions {
114	        strict: false,
115	        allow_empty_changesets: true,
116	    };
117	    let plan = plan_version(&workspace, &inference, &options)?;
118	    let decision = ReleasePrDecisionV2::derive(plan.pending_release().as_ref(), &config, &snapshot)?;
119	
120	    match global.format {
121	        OutputFormat::Json => emit_report(
122	            &mut std::io::stdout(),
123	            &ReleasePrDecideReport { decision },
124	            global.dry_run,
125	        )?,
126	        OutputFormat::Text => render_decision(&decision)?,
127	    }
128	    Ok(ExitCode::SUCCESS)
129	}
130	
131	/// A release PR merge must consume changesets, which pre mode keeps, so it fails before a PR is opened.
132	fn reject_pre_mode(workspace: &Workspace<'_, CliCommandRunner, ManifestWalkResolver>) -> Result<(), CliError> {
133	    let path = workspace.root.join(workspace.config.pre_json_path());
134	    let text = callisto_model::strict_fs::read_optional(&path).map_err(|error| GraphError::PreJsonRead {
135	        path: path.clone(),
136	        message: error.to_string(),
137	    })?;
138	    let Some(text) = text else { return Ok(()) };
139	    let state = parse_pre_json(&text).map_err(GraphError::PreJson)?;
140	    match state.mode {
141	        PreMode::Pre => Err(CliError::ReleasePrInPreMode { tag: state.tag }),
142	        PreMode::Exit => Ok(()),
143	    }
144	}
145	
146	fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
147	    let out = args
148	        .out
149	        .map(|path| OutputFile::new(global.resolve_file_arg(&path), global.dry_run, OutputKind::CommitPlan))
150	        .transpose()?;
151	    let base_commit = CommitSha::parse(&args.base_commit)?;
152	
153	    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
154	        source,
155	        path: Some(global.cwd.clone()),
156	    })?;
157	    let runner = CliCommandRunner;
158	    let git = GitAccess::new(&start, &runner);
159	    let changes = git.staged_changes_since(&base_commit)?;
160	    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;
161	
162	    match out {
163	        Some(out) => {
164	            let permit = out.permit();
165	            out.commit(&permit, &plan)?;
166	        }
167	        None => emit_report(
168	            &mut std::io::stdout(),
169	            &ReleasePrCommitPlanReport { plan },
170	            global.dry_run,
171	        )?,
172	    }
173	    Ok(ExitCode::SUCCESS)
174	}
175	
176	fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
177	    match &decision.action {
178	        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
179	        ReleasePrActionV2::Create { branch, staging_branch } => {
180	            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
181	        }
182	        ReleasePrActionV2::Update {
183	            pull_request_number,
184	            branch,
185	            expected_head_commit,
186	            staging_branch,
187	        } => emit_line(&format!(
188	            "release PR: update #{pull_request_number} ({branch}, expected head {}, staging {staging_branch})",
189	            expected_head_commit.as_str()
190	        ))?,
191	        _ => emit_line("release PR: unsupported decision")?,
192	    }
193	    Ok(())
194	}
