            return Err(ReleasePrDecisionError::DuplicatePullRequestNumber);
        }
        open_pull_requests.sort_by_key(|pr| pr.number);
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            repository,
            base_branch,
            base_commit,
            open_pull_requests,
        })
    }
}

/// The on-the-wire shape of [`ReleasePrSnapshotV2`], before its invariants are checked.
/// See [`ReleasePrConfigWireV1`] for why the CLI deserializes this instead of
