            wire.repository,
            wire.base_branch,
            wire.base_commit,
            wire.open_pull_requests,
        )
    }
}

impl TryFrom<ReleasePrSnapshotWireV2> for ReleasePrSnapshotV2 {
    type Error = ReleasePrDecisionError;

    fn try_from(wire: ReleasePrSnapshotWireV2) -> Result<Self, Self::Error> {
        Self::from_wire(wire)
    }
}

