/// Why a release-PR run is intentionally mutation-free.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
#[non_exhaustive]
pub enum ReleasePrNoopReasonV1 {
    NoPendingChangesets,
}

/// Versioned output of managed release-PR policy derivation.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(try_from = "ReleasePrDecisionWireV2", rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleasePrDecisionV2 {
    pub schema_version: u8,
    pub config: ReleasePrConfigV1,
    pub snapshot: ReleasePrSnapshotV2,
    pub action: ReleasePrActionV2,
}

impl ReleasePrDecisionV2 {
    pub const SCHEMA_VERSION: u8 = 2;

    /// Derives the only permitted action from fresh workspace and forge facts; with nothing pending it is a no-op.
    pub fn derive(
        pending: Option<&PendingRelease>,
        config: &ReleasePrConfigV1,
        snapshot: &ReleasePrSnapshotV2,
    ) -> Result<Self, ReleasePrDecisionError> {
        let release = Self::release_action(config, snapshot)?;
        let action = match pending {
            Some(_) => release,
            None => ReleasePrActionV2::Noop {
                reason: ReleasePrNoopReasonV1::NoPendingChangesets,
            },
        };
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            config: config.clone(),
            snapshot: snapshot.clone(),
            action,
        })
    }

    /// The create or update a pending release takes against this snapshot.
    fn release_action(
        config: &ReleasePrConfigV1,
        snapshot: &ReleasePrSnapshotV2,
    ) -> Result<ReleasePrActionV2, ReleasePrDecisionError> {
        if snapshot.repository != config.repository || snapshot.base_branch != config.base_branch {
            return Err(ReleasePrDecisionError::SnapshotIdentityMismatch);
        }

        let staging_branch = config.staging_branch();
        let mut eligible = Vec::new();
        for pr in &snapshot.open_pull_requests {
            if pr.head_branch == staging_branch {
                return Err(ReleasePrDecisionError::StagingBranchPullRequest { number: pr.number });
            }
            let shape = managed_branch_shape(&config.release_branch, &pr.head_branch)?;
            if shape.is_some() {
                if pr.head_repository != config.repository {
                    return Err(ReleasePrDecisionError::ForeignManagedPullRequest {
                        number: pr.number,
                        repository: pr.head_repository.clone(),
                    });
                }
                eligible.push(pr);
            }
        }
        if eligible.len() > 1 {
            return Err(ReleasePrDecisionError::AmbiguousManagedPullRequests { count: eligible.len() });
        }

        Ok(match eligible.first() {
            Some(pr) => ReleasePrActionV2::Update {
                pull_request_number: pr.number,
                branch: pr.head_branch.clone(),
                expected_head_commit: pr.head_commit.clone(),
                staging_branch,
            },
            None => ReleasePrActionV2::Create {
                branch: config.release_branch.clone(),
                staging_branch,
            },
        })
    }

    /// Rejects any post-decision forge state change before the executor mutates.
    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV2) -> Result<(), ReleasePrDecisionError> {
        if observed != &self.snapshot {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        Ok(())
    }

    /// Allows only the selected PR head change performed by this executor.
    pub fn verify_snapshot_after_update(
        &self,
        observed: &ReleasePrSnapshotV2,
        applied_head: &CommitSha,
    ) -> Result<(), ReleasePrDecisionError> {
        let ReleasePrActionV2::Update {
            pull_request_number, ..
        } = &self.action
        else {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        };
        if Self::release_action(&self.config, &self.snapshot)? != self.action {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        let mut expected = self.clone();
        let pr = expected
            .snapshot
            .open_pull_requests
            .iter_mut()
            .find(|pr| pr.number == *pull_request_number)
            .ok_or(ReleasePrDecisionError::SnapshotChanged)?;
        if &pr.head_commit == applied_head {
            return Err(ReleasePrDecisionError::SnapshotChanged);
        }
        pr.head_commit = applied_head.clone();
        expected.verify_snapshot(observed)
    }
}

/// The on-the-wire shape of [`ReleasePrDecisionV2`], with its nested config and
/// snapshot still unvalidated. See [`ReleasePrConfigWireV1`] for why the CLI
/// deserializes this instead of `ReleasePrDecisionV2` directly.
#[derive(Clone, Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleasePrDecisionWireV2 {
    pub schema_version: u8,
    pub config: ReleasePrConfigWireV1,
    pub snapshot: ReleasePrSnapshotWireV2,
    pub action: ReleasePrActionV2,
}

impl ReleasePrDecisionV2 {
    /// Validates an already-parsed wire value, including its nested config and snapshot,
    /// into a well-formed decision.
    pub fn from_wire(wire: ReleasePrDecisionWireV2) -> Result<Self, ReleasePrDecisionError> {
        check_schema_version(wire.schema_version, Self::SCHEMA_VERSION, "release PR decision")?;
        Ok(Self {
            schema_version: wire.schema_version,
            config: ReleasePrConfigV1::from_wire(wire.config)?,
            snapshot: ReleasePrSnapshotV2::from_wire(wire.snapshot)?,
            action: wire.action,
        })
    }
}

impl TryFrom<ReleasePrDecisionWireV2> for ReleasePrDecisionV2 {
    type Error = ReleasePrDecisionError;

    fn try_from(wire: ReleasePrDecisionWireV2) -> Result<Self, Self::Error> {
        Self::from_wire(wire)
    }
}

