fn plan(root: &Path, external: &Path, commit: &str) -> Output {
    callisto(
        root,
        &[
            "release",
            "plan",
            "--from-release-commit",
            commit,
            "--decision",
            DECISION_PATH,
            "--out",
            external.join("intent.json").to_str().unwrap(),
        ],
    )
}

fn assert_rejected(root: &Path, external: &Path, commit: &str, what: &str, reason: &str) {
    let out = plan(root, external, commit);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{what} must be rejected: {stderr}");
    assert!(stderr.contains("E165"), "{what} must fail with E165: {stderr}");
    assert!(stderr.contains(reason), "{what} must fail because `{reason}`: {stderr}");
    assert!(
        !external.join("intent.json").exists(),
        "{what} must not leave an intent behind"
    );
}

#[test]
fn an_untampered_release_commit_still_plans() {
    let (dir, release_commit) = release_commit_fixture();
    let external = tempfile::tempdir().unwrap();
    let out = plan(dir.path(), external.path(), &release_commit);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
}

/// A release inferred from commits alone consumes no changeset; its decision records none, and the commit plans.
#[test]
fn a_release_commit_inferred_from_commits_alone_plans() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    git(
        root,
        &["remote", "add", "origin", "https://github.com/example/core-crate.git"],
    );
    fs::write(
        root.join("Cargo.toml"),
        "[package]\nname = \"core-crate\"\nversion = \"0.1.0\"\nedition = \"2021\"\ndescription = \"t\"\nlicense = \"MIT\"\n",
    )
    .unwrap();
    fs::write(
        root.join("callisto.toml"),
        "[[package]]\nmatch = \"cargo/core-crate\"\nrelease-trigger = \"auto\"\npublish-to = [\"crates-io\"]\n",
    )
    .unwrap();
    fs::create_dir_all(root.join("src")).unwrap();
    fs::write(root.join("src/lib.rs"), "pub fn core() {}\n").unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "feat: core"]);

    let version = callisto(root, &["version", "--emit-decision", DECISION_PATH]);
    assert!(version.status.success(), "{}", String::from_utf8_lossy(&version.stderr));
    let decision: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(root.join(DECISION_PATH)).unwrap()).unwrap();
    assert_eq!(decision["consumedChangesets"], serde_json::json!([]));
    git(root, &["add", "-A"]);
    git(root, &["commit", "-q", "-m", "release core-crate"]);
    let release_commit = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &release_commit]);

    let external = tempfile::tempdir().unwrap();
    let out = plan(root, external.path(), &release_commit);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
}

#[test]
fn a_release_commit_in_a_workspace_below_the_repository_root_plans_and_still_refuses_edits_outside_it() {
    let (dir, release_commit) = release_commit_fixture_in(false, "ws");
    let root = dir.path();
    let runner = callisto_fixtures::git::GitRunner;
    let derive = |commit: &str| {
        let locator = callisto_graph::locate::IgnoreWalkLocator::new(&root.join("ws"));
        let workspace = callisto_graph::Workspace::load(root.join("ws"), &locator, &runner).unwrap();
        callisto_graph::commands::derive_release_commit_decision(
            &workspace,
            &callisto_model::CommitSha::parse(commit).unwrap(),
            Path::new(DECISION_PATH),
        )
        .map_err(Box::new)
    };
    derive(&release_commit).unwrap();

    fs::write(root.join("build.rs"), "fn main() {}\n").unwrap();
    git(root, &["add", "build.rs"]);
    git(root, &["commit", "-q", "--amend", "--no-edit"]);
    let tampered = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &tampered]);
    match *derive(&tampered).unwrap_err() {
        callisto_graph::GraphError::ReleaseCommitVerificationFailed {
            reason: callisto_graph::error::CommitVerificationFailure::UnexpectedPath { path },
            ..
        } => assert_eq!(path, "../build.rs"),
        other => panic!("expected the outside edit to be refused, got {other:?}"),
    }
}

#[test]
fn a_commit_that_does_not_write_the_decision_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    fs::write(root.join("crates/core/src/lib.rs"), "pub fn core() { /* later */ }\n").unwrap();
    git(root, &["commit", "-q", "-am", "unrelated follow-up"]);
    let follow_up = git(root, &["rev-parse", "HEAD"]);
    assert_ne!(follow_up, release_commit);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &follow_up,
        "a commit that carries a stale decision",
        "release-decision file was not written",
    );
}

#[test]
fn a_commit_that_leaves_a_recorded_changeset_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    let changesets: Vec<String> = git(
        root,
        &[
            "diff-tree",
            "--no-commit-id",
            "--name-only",
            "--diff-filter=D",
            "-r",
            &format!("{release_commit}^"),
            &release_commit,
        ],
    )
    .lines()
    .map(str::to_owned)
    .collect();
    assert!(!changesets.is_empty(), "fixture must consume a changeset");
    let skip: Vec<&str> = changesets.iter().map(String::as_str).collect();
    let commit = tampered_release_commit(root, &release_commit, &skip, &[]);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &commit,
        "a release commit that leaves the changeset in place",
        "changesets this commit deletes are not the ones",
    );
}

#[test]
fn a_commit_that_does_not_touch_the_changelog_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    let changelog = changed_path(root, &release_commit, "CHANGELOG.md");
    let commit = tampered_release_commit(root, &release_commit, &[&changelog], &[]);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &commit,
        "a release commit without its changelog entry",
        "changelog was not touched",
    );
}

#[test]
fn a_commit_that_does_not_change_the_released_manifest_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    let commit = tampered_release_commit(root, &release_commit, &[MANIFEST], &[]);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &commit,
        "a release commit that leaves the manifest version alone",
        "manifest is not part of this commit",
    );
}

#[test]
fn a_commit_whose_manifest_version_differs_from_the_decision_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    let wrong = "[package]\nname = \"core-crate\"\nversion = \"0.9.0\"\nedition = \"2021\"\n";
    let commit = tampered_release_commit(root, &release_commit, &[], &[(MANIFEST, wrong)]);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &commit,
        "a release commit that sets a different version than the decision",
        "manifest version does not match",
    );
}

