#[derive(Clone, Debug, Default)]
pub struct VersionOptions {
    pub strict: bool,
    pub allow_empty_changesets: bool,
}

fn map_reason_to_change_source(
    reason: &BumpReason,
    id: &callisto_model::PackageId,
    to: &callisto_model::Version,
    outcome: &crate::cascade::CascadeOutcome,
    agg: &crate::aggregate::Aggregation,
) -> Option<ChangeSource> {
    match reason {
        BumpReason::FixedGroupUnion { group } => Some(ChangeSource::GroupUnion {
            group: group.clone(),
            kind: GroupKind::Fixed,
        }),
        BumpReason::LinkedGroupUnion { group } => Some(ChangeSource::GroupUnion {
            group: group.clone(),
            kind: GroupKind::Linked,
        }),
        // Listed from `CascadeOutcome::dependency_updates`, which covers every bumped dependency, not just the first.
        BumpReason::Cascade { .. } => None,
        BumpReason::PeerEscalation { via, .. } => {
            let dep_to = outcome.targets.get(via).cloned().unwrap_or_else(|| to.clone());
            Some(ChangeSource::PeerEscalation {
                dependency: via.clone(),
                to: dep_to,
            })
        }
        BumpReason::Inference { commits, .. } => match agg.inference_commits.get(id).and_then(|c| c.first()) {
            Some((sha, subject)) => Some(ChangeSource::Commit {
                sha: sha.clone(),
                subject: subject.clone(),
            }),
            None => Some(ChangeSource::Changeset {
                filename: String::new(),
                summary: format!("Inferred version bump ({commits} commit(s))"),
            }),
        },
        _ => None,
    }
}

/// One "Dependency updates" entry per bumped dependency `id` was updated for, at the version it actually reached.
fn dependency_update_entries(
    id: &callisto_model::PackageId,
    severity: Severity,
    outcome: &crate::cascade::CascadeOutcome,
) -> Vec<ChangelogEntry> {
    let Some(updates) = outcome.dependency_updates.get(id) else {
        return Vec::new();
    };
    updates
        .iter()
        .filter_map(|(dependency, dep_kind)| {
            let to = outcome.targets.get(dependency)?.clone();
            Some(ChangelogEntry {
                severity,
                source: ChangeSource::DependencyUpdate {
                    dependency: dependency.clone(),
                    dep_kind: *dep_kind,
                    to,
                },
            })
        })
        .collect()
}

/// The GitHub repository compare links point to: the configured `[release] forge-repository`, else `origin`'s. No remote
/// or a remote that is not on github.com means no link, not an error.
fn changelog_repository<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
) -> Option<callisto_model::GitHubRepository> {
    ws.config
        .product_release
        .as_ref()
        .and_then(|release| release.forge_repository.clone())
        .or_else(|| {
            crate::commands::release::optional_git_remote(&ws.root, ws.runner)
                .ok()
                .flatten()
                .and_then(|remote| remote.github_repository)
        })
}

/// `reference` as a URL path segment. A tag template may use `#`, `?` or `%`, which would turn the rest of the compare
/// range into a fragment or a query; `/`, `@`, `+` and `:` are fine in a path and git refs use them.
fn encode_ref(reference: &str) -> String {
    reference.bytes().fold(String::new(), |mut out, byte| {
        if byte.is_ascii_alphanumeric() || b"-._~/@+:".contains(&byte) {
            out.push(char::from(byte));
        } else {
            out.push_str(&format!("%{byte:02X}"));
        }
        out
    })
}

/// The header facts for `id`'s section. A compare link needs a known repository and a tag on the previous version.
fn changelog_style<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    repository: Option<&callisto_model::GitHubRepository>,
    tags: &crate::TagIndex,
    id: &callisto_model::PackageId,
    from: &callisto_model::Version,
    to: &callisto_model::Version,
    date: Option<&str>,
) -> ChangelogStyle {
    let compare_url = repository
        .zip(crate::commands::release_decision::tag_of_version(tags, id, from))
        .map(|(repository, previous)| {
            let next = tags.template(id).render(to);
            format!(
                "https://github.com/{}/compare/{}...{}",
                repository.as_slug(),
                encode_ref(&previous.to_string()),
                encode_ref(&next.to_string())
            )
        });
    ChangelogStyle {
        layout: ws.config.changelog_layout,
        date: date.map(str::to_owned),
        compare_url,
    }
}

